mapper.select:
SELECT DISTINCT concat(BUG.BUGID,'__b') problemid,BUG.BUGNUMBER code,o.orgname company,'缺陷' source,BUG.DISCOVERPERSON discoverer,sa.REALNAME zgzxxrname, bug.BUGDESCRIPTE details,RE.STATUS STATUS,re.REFORMID REFORMID,RE.REFORMRESULT,RE.REFORMMEASURE,RE.REFORMCARRYOUT FROM TBL_NBSJ_BUG bug LEFT JOIN TBL_NBSJ_REFOPM re ON BUG.BUGID = RE.BUGID LEFT JOIN TBL_ORGANIZATION o ON o.orgid = BUG.BUGDEPARTMENT LEFT JOIN TBL_STAFF sa ON re.PERONINCHARGE = SA.STAFFID
BUG.NEEDREFORM = '是' AND BUG.INBUGIDB IS NULL AND RE.STATUS != 0 AND (RE.LASTREFORMSTATUS is null or RE.LASTREFORMSTATUS = 1) AND SOLUTIONID = #{solutionid}
and BUG.BUGNUMBER like concat(concat('%',#{re.code}),'%')
UNION ALL SELECT DISTINCT concat(QU.QUESTIONID,'__p') problemid, AA.SHEETCODE code,aa.orgname company,'审计发现' source,AA.REALNAME discoverer, bb.REALNAME zgzxxrname,substr(aa.AUDITDISCOVERABLE,400,1) details,bb.STATUS STATUS, bb.REFORMID REFORMID,bb.REFORMRESULT,bb.REFORMMEASURE,bb.REFORMCARRYOUT FROM TBL_NBSJ_QUESTION qu LEFT JOIN (SELECT SH.SHEETID,SA.REALNAME,SH.PROJECTID,SH.SHEETCODE,SH.CREATESTAFF,ORG.ORGNAME,SH.AUDITDISCOVERABLE FROM TBL_NBSJ_SHEET sh LEFT JOIN TBL_STAFF sa ON SH.CREATESTAFF = SA.STAFFID LEFT JOIN TBL_ORGANIZATION org ON sh.AUDITORG = ORG.ORGID ) aa ON QU.SHEETID = AA.SHEETID LEFT JOIN ( SELECT RE.QUESTIONID,SA.REALNAME,RE.STATUS,RE.LASTREFORMSTATUS,RE.SOLUTIONID,re.REFORMID,RE.REFORMRESULT,RE.REFORMMEASURE,RE.REFORMCARRYOUT FROM TBL_NBSJ_REFOPM re LEFT JOIN TBL_STAFF sa ON re.PERONINCHARGE = SA.STAFFID ) bb ON BB.QUESTIONID =QU.QUESTIONID WHERE 1 = 1 AND QU.RECSTATUS = 1 AND bb.status <> 0 and (bb.LASTREFORMSTATUS is null or bb.LASTREFORMSTATUS=1) and bb.SOLUTIONID= #{solutionid}
and SHEETCODE like concat(concat('%',#{re.code}),'%')
ORDER BY problemid

SELECT DISTINCT concat(BUG.BUGID,'__b') problemid,BUG.BUGNUMBER code,o.orgname company,'缺陷' source,BUG.DISCOVERPERSON discoverer,sa.REALNAME zgzxxrname,bug.BUGDESCRIPTE details,RE.STATUS STATUS,re.REFORMID REFORMID,RE.REFORMRESULT,RE.REFORMMEASURE,RE.REFORMCARRYOUT FROM TBL_NBSJ_BUG bug LEFT JOIN TBL_NBSJ_REFOPM re ON BUG.BUGID = RE.BUGID LEFT JOIN TBL_ORGANIZATION o ON o.orgid = BUG.BUGDEPARTMENT LEFT JOIN TBL_STAFF sa ON re.PERONINCHARGE = SA.STAFFID
BUG.NEEDREFORM = '是' AND BUG.INBUGIDB IS NULL AND SOLUTIONID = #{solutionid}
and BUG.BUGNUMBER like concat(concat('%',#{re.code}),'%')
AND RE.STATUS <> 0 AND (RE.LASTREFORMSTATUS is null or RE.LASTREFORMSTATUS=1)
AND RE.STATUS <> 0 AND RE.LASTREFORMSTATUS=1 and re.status <> 3 AND sa.staffid = #{re.peronincharge}
UNION ALL SELECT DISTINCT concat(QU.QUESTIONID,'__p') problemid, AA.SHEETCODE code,aa.ORGIDNAMES company,'审计发现' source,AA.REALNAME discoverer,bb.REALNAME zgzxxrname,substr(aa.AUDITDISCOVERABLE,400,1) details,bb.STATUS STATUS,bb.REFORMID REFORMID,bb.REFORMRESULT,bb.REFORMMEASURE,bb.REFORMCARRYOUT FROM TBL_NBSJ_QUESTION qu LEFT JOIN ( SELECT SH.SHEETID,SA.REALNAME,SH.PROJECTID,SH.SHEETCODE,SH.CREATESTAFF,ORG.ORGNAME,SH.AUDITDISCOVERABLE,SH.ORGIDNAMES FROM TBL_NBSJ_SHEET sh LEFT JOIN TBL_STAFF sa ON SH.CREATESTAFF = SA.STAFFID LEFT JOIN TBL_ORGANIZATION org ON sh.AUDITORG = ORG.ORGID ) aa ON QU.SHEETID = AA.SHEETID LEFT JOIN ( SELECT RE.QUESTIONID,SA.REALNAME,RE.STATUS,RE.LASTREFORMSTATUS,RE.SOLUTIONID,re.REFORMID,re.PERONINCHARGE,RE.REFORMRESULT,RE.REFORMMEASURE,RE.REFORMCARRYOUT FROM TBL_NBSJ_REFOPM re LEFT JOIN TBL_STAFF sa ON re.PERONINCHARGE = SA.STAFFID ) bb ON BB.QUESTIONID = QU.QUESTIONID WHERE 1 = 1 AND QU.RECSTATUS = 1 and bb.SOLUTIONID= #{solutionid}
and SHEETCODE like concat(concat('%',#{re.code}),'%')
AND bb.status != 0 and ( bb.LASTREFORMSTATUS is null or bb.LASTREFORMSTATUS =1)
AND bb.status != 0 and bb.LASTREFORMSTATUS =1 AND bb.status <> 3 AND bb.PERONINCHARGE = #{re.peronincharge}
ORDER BY problemid
